#include "exercise.h"
#include <ctype.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
char *recite(unsigned a, unsigned b) {
    const char *o[] = {"first",   "second", "third", "fourth", "fifth",    "sixth",
                       "seventh", "eighth", "ninth", "tenth",  "eleventh", "twelfth"};
    const char *g[] = {"a Partridge in a Pear Tree",
                       "two Turtle Doves",
                       "three French Hens",
                       "four Calling Birds",
                       "five Gold Rings",
                       "six Geese-a-Laying",
                       "seven Swans-a-Swimming",
                       "eight Maids-a-Milking",
                       "nine Ladies Dancing",
                       "ten Lords-a-Leaping",
                       "eleven Pipers Piping",
                       "twelve Drummers Drumming"};
    char *out = (char *)calloc(16000, 1);
    if (a < 1 || b > 12 || a > b)
        return out;
    for (unsigned i = a; i <= b; i++) {
        if (i > a)
            strcat(out, "\n");
        sprintf(out + strlen(out),
                "On the %s day of Christmas my true love gave to me: ", o[i - 1]);
        for (int j = (int)i - 1; j >= 0; j--) {
            strcat(out, g[j]);
            if (j == 1)
                strcat(out, ", and ");
            else if (j > 1)
                strcat(out, ", ");
        }
        strcat(out, ".");
    }
    return out;
}

