#include "exercise.h"
#include <assert.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static bool positive(int x) { return x > 0; }
static bool bstring(const void *p) { return (*(const char *const *)p)[0] == 98; }
static void string_length(const void *p, void *out) {
    *(size_t *)out = strlen(*(const char *const *)p);
}
int main(void) {
    char *s = recite(2, 2);
    assert(!strcmp(s, "On the second day of Christmas my true love gave to me: two "
                      "Turtle Doves, and a Partridge in a Pear Tree."));
    free(s);
    s = recite(1, 12);
    assert(strstr(s, "twelve Drummers Drumming") && strstr(s, "first day"));
